<template><article class="metric-card" :class="{ selected }" :data-testid="testId"><button type="button" :aria-pressed="selected" @click="$emit('select')"><span>{{ title }}</span><strong>{{ value }}</strong><DashboardStatusBadge :status="result.status" /><small v-if="result.status === 'partial'">{{ t("dashboard.knownPartialLowerBound") }} · {{ t("dashboard.readyRepos") }}: {{ result.readyRepoCount }}/{{ result.totalRepoCount }} · {{ t(`dashboard.reason.${result.partialReason}`) }}</small><small v-else-if="result.status === 'unavailable'">{{ t("dashboard.readyRepos") }}: {{ result.readyRepoCount }}/{{ result.totalRepoCount }} · {{ t(`dashboard.reason.${result.unavailableReason}`) }}</small><small>{{ comparisonLabel }}</small></button></article></template>
<script setup lang="ts">import { computed } from "vue"; import { useI18n } from "vue-i18n"; import type { DashboardData } from "@agent-workbench/shared"; import { formatComparison } from "../dashboard-formatters"; import DashboardStatusBadge from "./DashboardStatusBadge.vue"; type GitMetric = DashboardData["git"]["metrics"][keyof DashboardData["git"]["metrics"]] | DashboardData["overview"]["gitCommits"]; const props=defineProps<{title:string;value:string;result:GitMetric;selected:boolean;testId?:string}>(); defineEmits<{select:[]}>(); const {t,locale}=useI18n(); const comparisonLabel=computed(()=>props.result.comparison.status==="available"?formatComparison(props.result.comparison,locale.value):t(`dashboard.comparison.${props.result.comparison.status}`));</script><style scoped>.metric-card{min-width:0;background:var(--panel-bg-elevated);border:1px solid var(--border-color);border-radius:8px;padding:14px}.metric-card.selected{border-color:var(--primary-color);box-shadow:0 0 0 1px var(--primary-color)}button{all:unset;display:grid;gap:6px;cursor:pointer;width:100%}button:focus-visible{outline:2px solid var(--primary-color)}span,small{font-size:12px;color:var(--text-color-secondary)}strong{font-size:23px}</style>
